#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    char grid[505][505];
    for (int i = 0; i < N; i++) {
        scanf("%s", grid[i]);
    }

    int start_j = -1;
    for (int j = 0; j < M; j++) {
        if (grid[0][j] == 'o') {
            start_j = j;
            break;
        }
    }

    if (start_j == -1) return 0;

    int *queue = (int *)malloc(N * M * sizeof(int));
    int head = 0, tail = 0;
    queue[tail++] = start_j;

    while (head < tail) {
        int idx = queue[head++];
        int i = idx / M;
        int j = idx % M;

        if (i + 1 < N) {
            char below = grid[i + 1][j];
            if (below == '.') {
                grid[i + 1][j] = 'o';
                queue[tail++] = (i + 1) * M + j;
            } else if (below == '#') {
                if (j - 1 >= 0 && grid[i][j - 1] == '.') {
                    grid[i][j - 1] = 'o';
                    queue[tail++] = i * M + (j - 1);
                }
                if (j + 1 < M && grid[i][j + 1] == '.') {
                    grid[i][j + 1] = 'o';
                    queue[tail++] = i * M + (j + 1);
                }
            }
        }
    }

    for (int i = 0; i < N; i++) {
        printf("%s\n", grid[i]);
    }

    free(queue);
    return 0;
}
